def _get_argvalue(name, args, kwargs, func_code=None):
    """Get value of an argument by name from args and kwargs."""
    if name in kwargs:
        return kwargs[name]

    # Try to find by position
    if func_code is None:
        raise TypeError("Cannot determine argument position")

    varnames = func_code.co_varnames
    # Search through all varnames including keyword-only
    for i, vn in enumerate(varnames):
        if vn == name:
            if i < func_code.co_argcount:
                if i < len(args):
                    return args[i]
            elif func_code.co_kwonlyargcount and i >= func_code.co_argcount:
                # This is a keyword-only arg - must be in kwargs
                raise TypeError("Missing required keyword-only argument %r" % name)
            break

    raise TypeError("Argument %r not found" % name)

